            card.find("div", {"class": "temperature"}).text.strip().split("°")[0] + "°"
        )
        weather_["Phrase"] = remove_special_chars(
            card.find("div", {"class": "phrase"}).text.strip()
        )

        for item in card.find("div", {"class": "panels"}).find_all(
            "p", class_="panel-item"
